	inline bool IsStandardModelOmod(std::uint32_t a_omod)
	{
		std::uint32_t lo = 0;
		std::uint32_t hi = static_cast<std::uint32_t>(sizeof(kStandardModelOmods) / sizeof(kStandardModelOmods[0]));
		while (lo < hi) {
			const auto mid = lo + (hi - lo) / 2;
			if (kStandardModelOmods[mid] < a_omod) {
				lo = mid + 1;
			} else {
				hi = mid;
			}
		}
		return lo < sizeof(kStandardModelOmods) / sizeof(kStandardModelOmods[0]) && kStandardModelOmods[lo] == a_omod;
	}

	inline std::uint32_t LookupOmodMnam(std::uint32_t a_omod)
	{
		std::uint32_t lo = 0;
		std::uint32_t hi = static_cast<std::uint32_t>(sizeof(kOmodMnamTable) / sizeof(kOmodMnamTable[0]));
		while (lo < hi) {
			const auto mid = lo + (hi - lo) / 2;
			if (kOmodMnamTable[mid].omod < a_omod) {
				lo = mid + 1;
			} else {
				hi = mid;
			}
		}
		if (lo < sizeof(kOmodMnamTable) / sizeof(kOmodMnamTable[0]) && kOmodMnamTable[lo].omod == a_omod) {
			return kOmodMnamTable[lo].mnam;
		}
		return 0;
	}
